import json

with open('/prediction.json', 'r') as f:
    data = json.load(f)

kernel_2d = data['vllm/attention/ops/triton_unified_attention.py']['kernel_unified_attention_2d']

# Check key optimization markers
markers = ['max_query_pos_in_block', 'max_key_block', 'start_block', 'for j in range(start_block, max_key_block + 1):']
for marker in markers:
    if marker in kernel_2d:
        print(f'✓ Found marker: {marker}')
    else:
        print(f'✗ Missing marker: {marker}')

# Check that we don't have the old loop
if 'for j in range(0, num_blocks):' in kernel_2d:
    print('✗ Still has old loop!')
else:
    print('✓ Old loop replaced')
""}

